import numpy as np
from scipy.optimize import minimize
def fun(x): return x[0] - np.log(x[0]) if x[0] > 0 else np.nan
def jac(x): return np.array([1 - 1/x[0]])
def hess(x):
    if x[0] <= 0: raise ValueError('Hessian evaluated outside domain')
    return np.array([[1/x[0]**2]])
r = minimize(fun, [2.1], jac=jac, hess=hess, method='trust-exact', tol=1e-8,
             options={'initial_trust_radius': 10, 'maxiter': 10})
print(r.success, r.x)
